"use client"

import * as React from "react"

import { clearDocxDocumentResource } from "@/lib/docx-document-resource"
import { isResourceError, isViewerFormatError } from "@/lib/viewer-errors"
import { createViewerResource } from "@/lib/viewer-resource"
import { useIsClient } from "@/components/ui/use-is-client"
import { ViewerErrorBoundary } from "@/components/ui/viewer-error"

import { DocxViewerFallback } from "./docx-viewer-chrome"
import { DocxViewerContent } from "./docx-viewer-content"
import type {
  DocxResourceViewerProps,
  DocxViewerHandle,
  DocxViewerProps,
} from "./docx-viewer-types"

export type {
  DocxDocumentSource,
  DocxResourceViewerProps,
  DocxTarget,
  DocxViewerHandle,
  DocxViewerProps,
  DocxViewerSlots,
} from "./docx-viewer-types"

export const DocxViewer = React.forwardRef<DocxViewerHandle, DocxViewerProps>(
  function DocxViewer(props, ref) {
    const { source, ...resourceProps } = props
    const resource = React.useMemo(() => createViewerResource(source), [source])
    return (
      <DocxResourceViewer {...resourceProps} ref={ref} resource={resource} />
    )
  }
)

export const DocxResourceViewer = React.forwardRef<
  DocxViewerHandle,
  DocxResourceViewerProps
>(function DocxResourceViewer(props, ref) {
  const isClient = useIsClient()
  const resource = props.resource
  if (!isClient) {
    return (
      <DocxViewerFallback
        bare={props.bare}
        className={props.className}
        slots={props.slots}
        toolbar={props.toolbar}
      />
    )
  }
  return (
    <ViewerErrorBoundary
      bare={props.bare}
      className={props.className}
      download={resource.originalDownload}
      format="docx"
      onRetry={(error) => {
        if (isResourceError(error) || !isViewerFormatError(error)) {
          clearDocxDocumentResource(resource.content)
        }
      }}
      resetKey={resource.keys.resource}
      sourceKind={resource.sourceKind}
    >
      <React.Suspense
        fallback={
          <DocxViewerFallback
            bare={props.bare}
            className={props.className}
            slots={props.slots}
            toolbar={props.toolbar}
          />
        }
      >
        <DocxViewerContent {...props} forwardedRef={ref} resource={resource} />
      </React.Suspense>
    </ViewerErrorBoundary>
  )
})

import type { ViewerResource } from "@/lib/viewer-resource"
import type { BlobViewerSource, UrlViewerSource } from "@/lib/viewer-source"

import type { ViewerSlots } from "./viewer-slots"

export type DocxDocumentSource = UrlViewerSource | BlobViewerSource

export type DocxTarget =
  | { kind: "text"; text: string }
  | { kind: "cell"; table: number; row: number; column: number }

export interface DocxViewerHandle {
  scrollToTarget: (target: DocxTarget, options?: ScrollIntoViewOptions) => void
  getViewportElement: () => HTMLDivElement | null
}

export type DocxViewerSlots = ViewerSlots

export interface DocxViewerProps {
  source: DocxDocumentSource
  className?: string
  scale?: number
  defaultScale?: number
  onScaleChange?: (scale: number | null) => void
  toolbar?: boolean
  highlight?: DocxTarget | null
  onVisiblePageChange?: (page: number) => void
  onScrollProgressChange?: (progress: number) => void
  bare?: boolean
  slots?: DocxViewerSlots
}

export type DocxResourceViewerProps = Omit<DocxViewerProps, "source"> & {
  resource: ViewerResource
}

import type * as DocxPreview from "docx-preview"

import {
  isViewerFormatError,
  ViewerFormatError,
  type ViewerFormatErrorMapperOptions,
} from "@/lib/viewer-errors"

export const DOCX_MIN_SCALE = 0.25
export const DOCX_MAX_SCALE = 5
export const DOCX_ZOOM_STEP = 1.2

export const DEFAULT_DOCX_PAGE_WIDTH = 816
export const DEFAULT_DOCX_PAGE_HEIGHT = 1056

export const DOCX_RENDER_OPTIONS: Partial<DocxPreview.Options> = {
  inWrapper: true,
  breakPages: true,
  ignoreLastRenderedPageBreak: false,
  experimental: true,
  renderHeaders: true,
  renderFooters: true,
  renderFootnotes: true,
}

export const DOCX_SCOPED_STYLES = `
[data-slot="docx-viewer"] .docx-wrapper {
  background: transparent;
  padding: 0;
  gap: 1rem;
}
[data-slot="docx-viewer"] .docx-wrapper > section.docx {
  margin-bottom: 0;
  box-shadow: 0 0 0 1px var(--border), 0 1px 2px 0 rgb(0 0 0 / 0.05);
}`

export function clampDocxScale(value: number) {
  return clamp(value, DOCX_MIN_SCALE, DOCX_MAX_SCALE)
}

export function normalizeDocxScale(value: number | null | undefined) {
  if (value == null) return null
  if (Number.isNaN(value)) return 1
  return clampDocxScale(value)
}

export function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value))
}

export function positivePixel(value: number) {
  return Number.isFinite(value) && value > 0 ? value : null
}

export function toDocxFormatError(
  error: unknown,
  options: ViewerFormatErrorMapperOptions
): ViewerFormatError {
  if (isViewerFormatError(error)) return error
  return new ViewerFormatError({
    format: "docx",
    kind: options.kind,
    message: options.message,
    cause: error,
  })
}

import type * as DocxPreview from "docx-preview"

import { ViewerFormatError } from "@/lib/viewer-errors"

import {
  DEFAULT_DOCX_PAGE_HEIGHT,
  DEFAULT_DOCX_PAGE_WIDTH,
  DOCX_RENDER_OPTIONS,
  positivePixel,
} from "./docx-viewer-core"

let docxPromise: Promise<typeof DocxPreview> | null = null

export function loadDocxPreview() {
  if (!docxPromise) {
    docxPromise = import("docx-preview").catch((error) => {
      docxPromise = null
      throw error
    })
  }
  return docxPromise
}

export async function renderDocxPreview(buffer: ArrayBuffer) {
  const { renderAsync } = await loadDocxPreview()
  const renderHost = document.createElement("div")
  await renderAsync(buffer, renderHost, undefined, DOCX_RENDER_OPTIONS)
  return renderHost
}

export function commitDocxRender({
  host,
  renderHost,
  scale,
}: {
  host: HTMLElement
  renderHost: HTMLElement
  scale: number
}) {
  host.replaceChildren(...Array.from(renderHost.childNodes))
  const pages = Array.from(
    host.querySelectorAll<HTMLElement>(".docx-wrapper > section.docx")
  )
  if (!pages.length) {
    throw new ViewerFormatError({
      format: "docx",
      kind: "render_failed",
      message: "DOCX render produced no pages.",
    })
  }
  const z = scale || 1
  const sizes = pages.map((el) => {
    const r = el.getBoundingClientRect()
    const width = positivePixel(Math.round(r.width / z))
    const height = positivePixel(Math.round(r.height / z))
    return [
      width ?? DEFAULT_DOCX_PAGE_WIDTH,
      height ?? DEFAULT_DOCX_PAGE_HEIGHT,
    ] as const
  })
  pages.forEach((el, i) => {
    el.dataset.pageNumber = String(i + 1)
    el.style.contentVisibility = "auto"
    el.style.containIntrinsicSize = `${sizes[i][0]}px ${sizes[i][1]}px`
  })
  return {
    numPages: pages.length,
    pageWidth: pages.length ? sizes[0][0] : null,
  }
}

import * as React from "react"

import {
  clampDocxScale,
  DOCX_ZOOM_STEP,
  normalizeDocxScale,
} from "./docx-viewer-core"

export function useDocxViewerScale({
  containerWidth,
  defaultScale,
  onScaleChange,
  pageWidth,
  resetKey,
  scale: controlledScale,
}: {
  containerWidth: number | null
  defaultScale?: number
  onScaleChange?: (scale: number | null) => void
  pageWidth: number | null
  resetKey: string
  scale?: number
}) {
  const normalizedControlledScale = normalizeDocxScale(controlledScale)
  const isScaleControlled = controlledScale != null
  const normalizedDefaultScale = normalizeDocxScale(defaultScale)
  const [manualScale, setManualScale] = React.useState<number | null>(
    normalizedDefaultScale
  )

  React.useEffect(() => {
    setManualScale(normalizedDefaultScale)
  }, [normalizedDefaultScale, resetKey])

  const fitScale =
    containerWidth && pageWidth
      ? clampDocxScale((containerWidth - 32) / pageWidth)
      : 1
  const scale = normalizedControlledScale ?? manualScale ?? fitScale

  const setViewerScale = React.useCallback(
    (nextScale: number | null) => {
      const normalized = nextScale == null ? null : normalizeDocxScale(nextScale)
      if (isScaleControlled) {
        onScaleChange?.(normalized)
        return
      }
      setManualScale(normalized)
      onScaleChange?.(normalized)
    },
    [isScaleControlled, onScaleChange]
  )

  const zoomIn = React.useCallback(() => {
    setViewerScale(clampDocxScale(scale * DOCX_ZOOM_STEP))
  }, [scale, setViewerScale])

  const zoomOut = React.useCallback(() => {
    setViewerScale(clampDocxScale(scale / DOCX_ZOOM_STEP))
  }, [scale, setViewerScale])

  const fitWidth = React.useCallback(() => {
    setViewerScale(null)
  }, [setViewerScale])

  return {
    fitWidth,
    isScaleControlled,
    scale,
    setViewerScale,
    zoomIn,
    zoomOut,
  }
}

import * as React from "react"

import { clamp } from "./docx-viewer-core"

export function useDocxViewerScroll({
  onScrollProgressChange,
  onVisiblePageChange,
  ready,
}: {
  onScrollProgressChange?: (progress: number) => void
  onVisiblePageChange?: (page: number) => void
  ready: boolean
}) {
  const scrollViewportRef = React.useRef<HTMLDivElement | null>(null)
  const lastReported = React.useRef(0)
  const [currentPage, setCurrentPage] = React.useState(1)
  const scrollFrame = React.useRef(0)

  const resetScroll = React.useCallback(() => {
    setCurrentPage(1)
    lastReported.current = 0
    if (scrollViewportRef.current) scrollViewportRef.current.scrollTop = 0
  }, [])

  const measureScroll = React.useCallback(() => {
    scrollFrame.current = 0
    const viewport = scrollViewportRef.current
    if (!viewport) return
    const scrollable = viewport.scrollHeight - viewport.clientHeight
    onScrollProgressChange?.(
      scrollable > 0 ? clamp(viewport.scrollTop / scrollable, 0, 1) : 0
    )
    const rect = viewport.getBoundingClientRect()
    const marker = rect.top + rect.height * 0.2
    const pages = viewport.querySelectorAll<HTMLElement>("[data-page-number]")
    let current = 1
    for (const el of pages) {
      if (el.getBoundingClientRect().top <= marker) {
        current = Number(el.dataset.pageNumber)
      } else {
        break
      }
    }
    if (current && current !== lastReported.current) {
      lastReported.current = current
      setCurrentPage(current)
      onVisiblePageChange?.(current)
    }
  }, [onScrollProgressChange, onVisiblePageChange])

  const handleScroll = React.useCallback(() => {
    if (scrollFrame.current) return
    scrollFrame.current = -1
    const requestedFrame = requestAnimationFrame(measureScroll)
    if (scrollFrame.current === -1) scrollFrame.current = requestedFrame
  }, [measureScroll])

  React.useEffect(() => {
    if (ready) measureScroll()
  }, [measureScroll, ready])

  React.useEffect(
    () => () => {
      if (scrollFrame.current > 0) cancelAnimationFrame(scrollFrame.current)
    },
    []
  )

  return {
    currentPage,
    handleScroll,
    measureScroll,
    resetScroll,
    scrollViewportRef,
  }
}

import type { DocxTarget } from "./docx-viewer-types"

export interface DocxRenderIndex {
  text: string
  positions: Array<{ node: Text; offset: number }>
  cells: Map<string, HTMLElement>
}

const INLINE_TAGS = new Set([
  "SPAN",
  "A",
  "B",
  "I",
  "EM",
  "STRONG",
  "U",
  "S",
  "STRIKE",
  "DEL",
  "INS",
  "SMALL",
  "BIG",
  "SUB",
  "SUP",
  "MARK",
  "FONT",
  "CODE",
  "ABBR",
  "CITE",
  "Q",
  "TIME",
  "BDI",
  "BDO",
  "WBR",
  "LABEL",
  "VAR",
  "SAMP",
  "KBD",
  "TT",
  "NOBR",
])

export function buildDocxRenderIndex(root: HTMLElement): DocxRenderIndex {
  const textIndex = buildDocxTextIndex(root)
  return {
    text: textIndex.text,
    positions: textIndex.positions,
    cells: buildDocxCellIndex(root),
  }
}

export function resolveDocxTarget(
  index: DocxRenderIndex,
  target: DocxTarget
): Range | null {
  if (target.kind === "cell") {
    const cell = index.cells.get(cellKey(target.table, target.row, target.column))
    if (!cell) return null
    const range = document.createRange()
    range.selectNodeContents(cell)
    return range
  }

  const needle = normalizeTextTarget(target.text)
  if (!needle) return null
  const idx = index.text.indexOf(needle)
  if (idx === -1) return null
  const start = index.positions[idx]
  const end = index.positions[idx + needle.length - 1]
  if (!start || !end) return null
  const range = document.createRange()
  range.setStart(start.node, start.offset)
  range.setEnd(end.node, end.offset + 1)
  return range
}

export function targetKey(
  target: DocxTarget | null | undefined
): string | null {
  if (!target) return null
  return target.kind === "cell"
    ? `cell:${target.table}:${target.row}:${target.column}`
    : `text:${normalizeTextTarget(target.text)}`
}

export function normalizeTextTarget(text: string) {
  return text.replace(/\s+/g, " ").trim()
}

function buildDocxCellIndex(root: HTMLElement) {
  const cells = new Map<string, HTMLElement>()
  const tables = root.querySelectorAll(".docx-wrapper > section.docx table")
  tables.forEach((table, tableIndex) => {
    Array.from((table as HTMLTableElement).rows).forEach((row, rowIndex) => {
      Array.from(row.cells).forEach((cell, columnIndex) => {
        if (!hasHiddenAncestor(cell, root)) {
          cells.set(cellKey(tableIndex, rowIndex, columnIndex), cell)
        }
      })
    })
  })
  return cells
}

function buildDocxTextIndex(root: HTMLElement) {
  const walker = document.createTreeWalker(
    root,
    NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT
  )
  let normalized = ""
  const positions: { node: Text; offset: number }[] = []
  let prevSpace = false
  let prevBlock: HTMLElement | null = null
  let pendingBreak = false
  for (let n = walker.nextNode(); n; n = walker.nextNode()) {
    if (n.nodeType === Node.ELEMENT_NODE) {
      const tag = (n as HTMLElement).tagName
      if (
        (tag === "BR" || tag === "HR") &&
        isDocumentBreakElement(root, n as HTMLElement)
      ) {
        pendingBreak = true
      }
      continue
    }
    if (!isDocumentTextNode(root, n as Text)) continue
    const block = blockContainer((n as Text).parentElement, root)
    const broke = pendingBreak || (prevBlock !== null && block !== prevBlock)
    pendingBreak = false
    if (broke && !prevSpace && normalized) {
      prevSpace = true
      normalized += " "
      positions.push({ node: n as Text, offset: 0 })
    }
    prevBlock = block
    const data = (n as Text).data
    for (let i = 0; i < data.length; i++) {
      if (/\s/.test(data[i])) {
        if (prevSpace) continue
        prevSpace = true
        normalized += " "
      } else {
        prevSpace = false
        normalized += data[i]
      }
      positions.push({ node: n as Text, offset: i })
    }
  }
  return { text: normalized, positions }
}

function cellKey(table: number, row: number, column: number) {
  return `${table}:${row}:${column}`
}

function blockContainer(
  el: HTMLElement | null,
  root: HTMLElement
): HTMLElement {
  let cur = el
  while (cur && cur !== root && INLINE_TAGS.has(cur.tagName)) {
    cur = cur.parentElement
  }
  return cur ?? root
}

function isDocumentTextNode(root: HTMLElement, node: Text) {
  const parent = node.parentElement
  if (!parent || !root.contains(parent)) return false
  if (!parent.closest(".docx-wrapper > section.docx")) return false
  if (parent.closest("style, script, noscript, template")) return false
  return !hasHiddenAncestor(parent, root)
}

function isDocumentBreakElement(root: HTMLElement, el: HTMLElement) {
  if (!root.contains(el)) return false
  if (!el.closest(".docx-wrapper > section.docx")) return false
  return !hasHiddenAncestor(el, root)
}

function hasHiddenAncestor(element: HTMLElement, root: HTMLElement) {
  for (let el: HTMLElement | null = element; el; el = el.parentElement) {
    if (
      el.hidden ||
      el.getAttribute("aria-hidden")?.trim().toLowerCase() === "true"
    ) {
      return true
    }
    const style =
      typeof window !== "undefined" ? window.getComputedStyle(el) : el.style
    if (
      style.display === "none" ||
      style.visibility === "hidden" ||
      style.visibility === "collapse" ||
      style.getPropertyValue("content-visibility") === "hidden"
    ) {
      return true
    }
    if (el === root) break
  }
  return false
}

import * as React from "react"

import {
  resolveDocxTarget,
  targetKey,
  type DocxRenderIndex,
} from "./docx-viewer-targets"
import type { DocxTarget } from "./docx-viewer-types"

export function useDocxHighlight({
  highlight,
  renderIndex,
  ready,
}: {
  highlight?: DocxTarget | null
  renderIndex: DocxRenderIndex | null
  ready: boolean
}) {
  const highlightName = "docx-src-" + React.useId().replace(/:/g, "")
  const highlightKey = targetKey(highlight)

  React.useEffect(() => {
    const registry =
      typeof CSS !== "undefined" && "highlights" in CSS ? CSS.highlights : null
    if (!registry || typeof Highlight === "undefined") return
    const deleteHighlight = () => {
      try {
        registry.delete(highlightName)
      } catch {
        // Highlighting is an enhancement; registry failures must not hide the document.
      }
    }
    if (!highlight || !ready || !renderIndex) {
      deleteHighlight()
      return
    }
    try {
      const range = resolveDocxTarget(renderIndex, highlight)
      if (range) registry.set(highlightName, new Highlight(range))
      else deleteHighlight()
    } catch {
      deleteHighlight()
    }
    return deleteHighlight
    // highlight is read through the stable value key; object identity would thrash.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [highlightKey, ready, highlightName, renderIndex])

  return highlightName
}

"use client"

import * as React from "react"
import { Download, Maximize, Minus, Plus } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Separator } from "@/components/ui/separator"
import { Skeleton } from "@/components/ui/skeleton"
import { ViewerDownloadButton } from "@/components/ui/viewer-download"
import type { ViewerDownloadAction } from "@/lib/viewer-download"

import type { DocxViewerSlots } from "./docx-viewer-types"

export function DocxViewerFrame({
  bare = false,
  children,
  className,
}: {
  bare?: boolean
  children: React.ReactNode
  className?: string
}) {
  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "h-full bg-muted/20" : "rounded-xl border bg-muted/30",
        className
      )}
      data-slot="docx-viewer"
    >
      {children}
    </div>
  )
}

export function DocxViewerBody({
  children,
  slots,
}: {
  children: React.ReactNode
  slots?: DocxViewerSlots
}) {
  return (
    <div className="relative flex min-h-0 flex-1">
      {slots?.left ? (
        <div data-slot="docx-viewer-left" className="flex-shrink-0">
          {slots.left}
        </div>
      ) : null}
      <div className="flex min-h-0 min-w-0 flex-1 flex-col">
        {slots?.top ? (
          <div data-slot="docx-viewer-top">{slots.top}</div>
        ) : null}
        {children}
        {slots?.bottom ? (
          <div data-slot="docx-viewer-bottom">{slots.bottom}</div>
        ) : null}
      </div>
      {slots?.right ? (
        <div data-slot="docx-viewer-right" className="flex-shrink-0">
          {slots.right}
        </div>
      ) : null}
      {slots?.overlay ? (
        <div
          data-slot="docx-viewer-overlay"
          className="pointer-events-none absolute inset-0 z-20"
        >
          {slots.overlay}
        </div>
      ) : null}
    </div>
  )
}

export function DocxViewerToolbar({
  currentPage,
  download,
  fitWidth,
  numPages,
  ready,
  scale,
  zoomIn,
  zoomOut,
}: {
  currentPage: number
  download?: ViewerDownloadAction | null
  fitWidth: () => void
  numPages: number
  ready: boolean
  scale: number
  zoomIn: () => void
  zoomOut: () => void
}) {
  return (
    <div className="flex h-10 flex-shrink-0 items-center gap-1 border-b bg-card px-2">
      <span className="px-1 text-xs text-muted-foreground tabular-nums">
        {ready ? (
          <>
            Page {Math.min(currentPage, numPages)} of {numPages}
          </>
        ) : (
          <Skeleton className="inline-block h-3 w-12 align-middle" />
        )}
      </span>
      <div className="ml-auto flex items-center gap-1">
        <DocxToolbarButton label="Zoom out" onClick={zoomOut}>
          <Minus />
        </DocxToolbarButton>
        <span className="w-12 text-center text-xs text-muted-foreground tabular-nums">
          {ready ? (
            `${Math.round(scale * 100)}%`
          ) : (
            <Skeleton className="inline-block h-3 w-8 align-middle" />
          )}
        </span>
        <DocxToolbarButton label="Zoom in" onClick={zoomIn}>
          <Plus />
        </DocxToolbarButton>
        <DocxToolbarButton label="Fit width" onClick={fitWidth}>
          <Maximize />
        </DocxToolbarButton>
        <Separator orientation="vertical" className="mx-1 h-4" />
        {download ? <ViewerDownloadButton action={download} /> : null}
      </div>
    </div>
  )
}

export function DocxViewerFallback({
  bare = false,
  className,
  slots,
  toolbar = true,
}: {
  bare?: boolean
  className?: string
  slots?: DocxViewerSlots
  toolbar?: boolean
}) {
  return (
    <DocxViewerFrame bare={bare} className={className}>
      {toolbar ? <DocxToolbarSkeleton /> : null}
      <DocxViewerBody slots={slots}>
        <div className="min-h-0 flex-1 overflow-auto">
          <div className="flex flex-col items-center p-4">
            <DocxSkeleton />
          </div>
        </div>
      </DocxViewerBody>
    </DocxViewerFrame>
  )
}

export function DocxToolbarSkeleton() {
  return (
    <div className="flex h-10 flex-shrink-0 items-center gap-1 border-b bg-card px-2">
      <span className="px-1">
        <Skeleton className="inline-block h-3 w-12 align-middle" />
      </span>
      <div className="ml-auto flex items-center gap-1">
        <DocxToolbarPlaceholder>
          <Minus />
        </DocxToolbarPlaceholder>
        <span className="w-12 text-center">
          <Skeleton className="inline-block h-3 w-8 align-middle" />
        </span>
        <DocxToolbarPlaceholder>
          <Plus />
        </DocxToolbarPlaceholder>
        <DocxToolbarPlaceholder>
          <Maximize />
        </DocxToolbarPlaceholder>
        <Separator orientation="vertical" className="mx-1 h-4" />
        <DocxToolbarPlaceholder>
          <Download />
        </DocxToolbarPlaceholder>
      </div>
    </div>
  )
}

export function DocxSkeleton() {
  return (
    <Skeleton
      aria-hidden
      className="w-full rounded-sm"
      data-slot="docx-page-skeleton"
      style={{ aspectRatio: "8.5 / 11" }}
    />
  )
}

function DocxToolbarButton({
  label,
  children,
  ...props
}: React.ComponentProps<typeof Button> & { label: string }) {
  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className="size-7"
      aria-label={label}
      title={label}
      {...props}
    >
      {children}
    </Button>
  )
}

function DocxToolbarPlaceholder({ children }: { children: React.ReactNode }) {
  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className="size-7"
      disabled
      tabIndex={-1}
      aria-hidden
    >
      {children}
    </Button>
  )
}

"use client"

import * as React from "react"

import { getDocxDocumentResource } from "@/lib/docx-document-resource"
import { isAbortError, isResourceError } from "@/lib/viewer-errors"
import { ScrollArea } from "@/components/ui/scroll-area"

import {
  DocxSkeleton,
  DocxViewerBody,
  DocxViewerFrame,
  DocxViewerToolbar,
} from "./docx-viewer-chrome"
import { DOCX_SCOPED_STYLES, toDocxFormatError } from "./docx-viewer-core"
import { useDocxHighlight } from "./docx-viewer-highlight"
import { commitDocxRender, renderDocxPreview } from "./docx-viewer-render"
import { useDocxViewerScale } from "./docx-viewer-scale"
import { useDocxViewerScroll } from "./docx-viewer-scroll"
import {
  buildDocxRenderIndex,
  resolveDocxTarget,
  type DocxRenderIndex,
} from "./docx-viewer-targets"
import type {
  DocxResourceViewerProps,
  DocxViewerHandle,
} from "./docx-viewer-types"

export function DocxViewerContent({
  bare = false,
  className,
  defaultScale,
  forwardedRef,
  highlight,
  onScaleChange,
  onScrollProgressChange,
  onVisiblePageChange,
  resource,
  scale: controlledScale,
  slots,
  toolbar = true,
}: Omit<DocxResourceViewerProps, "source"> & {
  forwardedRef?: React.ForwardedRef<DocxViewerHandle>
}) {
  const buffer = React.use(
    getDocxDocumentResource(resource.content, { retainRejected: true })
  )
  const [containerWidth, setContainerWidth] = React.useState<number | null>(
    null
  )
  const [numPages, setNumPages] = React.useState(0)
  const [pageWidth, setPageWidth] = React.useState<number | null>(null)
  const [renderIndex, setRenderIndex] = React.useState<DocxRenderIndex | null>(
    null
  )
  const [ready, setReady] = React.useState(false)
  const [renderError, setRenderError] = React.useState<Error | null>(null)
  if (renderError) throw renderError

  const {
    currentPage,
    handleScroll,
    measureScroll,
    resetScroll,
    scrollViewportRef,
  } = useDocxViewerScroll({
    onScrollProgressChange,
    onVisiblePageChange,
    ready,
  })
  const { fitWidth, scale, zoomIn, zoomOut } = useDocxViewerScale({
    containerWidth,
    defaultScale,
    onScaleChange,
    pageWidth,
    resetKey: resource.keys.resource,
    scale: controlledScale,
  })
  const scaleRef = React.useRef(scale)
  React.useEffect(() => {
    scaleRef.current = scale
  })

  const containerRef = React.useCallback((el: HTMLDivElement | null) => {
    if (!el) return
    setContainerWidth(el.clientWidth)
    if (typeof ResizeObserver === "undefined") return
    let frame = 0
    let latest = el.clientWidth
    let observer: ResizeObserver | null = null
    try {
      observer = new ResizeObserver((entries) => {
        for (const entry of entries)
          latest = (entry.target as HTMLElement).clientWidth
        if (frame) return
        frame = -1
        const requestedFrame = requestAnimationFrame(() => {
          frame = 0
          setContainerWidth(latest)
        })
        if (frame === -1) frame = requestedFrame
      })
      observer.observe(el)
    } catch {
      if (frame > 0) cancelAnimationFrame(frame)
      observer?.disconnect()
      return
    }
    return () => {
      if (frame > 0) cancelAnimationFrame(frame)
      observer.disconnect()
    }
  }, [])

  const hostRef = React.useRef<HTMLDivElement | null>(null)
  const renderIndexRef = React.useRef<DocxRenderIndex | null>(null)
  React.useEffect(() => {
    const host = hostRef.current
    if (!host) return
    let cancelled = false
    setReady(false)
    setNumPages(0)
    setRenderIndex(null)
    renderIndexRef.current = null
    resetScroll()
    host.replaceChildren()
    renderDocxPreview(buffer)
      .then((renderHost) => {
        if (cancelled) return
        const result = commitDocxRender({
          host,
          renderHost,
          scale: scaleRef.current,
        })
        const nextRenderIndex = buildDocxRenderIndex(host)
        renderIndexRef.current = nextRenderIndex
        setRenderIndex(nextRenderIndex)
        setNumPages(result.numPages)
        setPageWidth(result.pageWidth)
        setReady(true)
      })
      .catch((err) => {
        if (!cancelled) {
          setRenderError(
            isResourceError(err) || isAbortError(err)
              ? err
              : toDocxFormatError(err, {
                  kind: "render_failed",
                  message: "Failed to render DOCX.",
                })
          )
        }
      })
    return () => {
      cancelled = true
    }
  }, [buffer, resetScroll])

  React.useEffect(() => {
    if (ready) measureScroll()
  }, [measureScroll, ready, scale])

  React.useEffect(() => {
    renderIndexRef.current = renderIndex
  }, [renderIndex])

  const highlightName = useDocxHighlight({
    highlight,
    renderIndex,
    ready,
  })

  React.useImperativeHandle(
    forwardedRef ?? null,
    () => ({
      scrollToTarget: (target, options) => {
        const index = renderIndexRef.current
        if (!index) return
        const node = resolveDocxTarget(index, target)?.startContainer
        const el =
          node?.nodeType === Node.ELEMENT_NODE
            ? (node as HTMLElement)
            : (node?.parentElement ?? null)
        el?.scrollIntoView({
          block: "center",
          inline: "nearest",
          behavior: options?.behavior ?? "smooth",
          ...options,
        })
      },
      getViewportElement: () => scrollViewportRef.current,
    }),
    [scrollViewportRef]
  )

  return (
    <DocxViewerFrame bare={bare} className={className}>
      <style>{DOCX_SCOPED_STYLES}</style>
      <style>{`::highlight(${highlightName}){background-color:color-mix(in oklab, var(--primary) 22%, transparent);}`}</style>
      {toolbar ? (
        <DocxViewerToolbar
          currentPage={currentPage}
          download={resource.originalDownload}
          fitWidth={fitWidth}
          numPages={numPages}
          ready={ready}
          scale={scale}
          zoomIn={zoomIn}
          zoomOut={zoomOut}
        />
      ) : null}
      <DocxViewerBody slots={slots}>
        <ScrollArea
          className="min-h-0 flex-1"
          viewportRef={scrollViewportRef}
          viewportProps={{ onScroll: handleScroll }}
        >
          <div ref={containerRef} className="flex flex-col items-center p-4">
            {!ready ? <DocxSkeleton /> : null}
            <div
              ref={hostRef}
              className={
                ready
                  ? "w-full opacity-100 transition-opacity duration-200"
                  : "w-full opacity-0 transition-opacity duration-200"
              }
              style={{ zoom: scale }}
            />
          </div>
        </ScrollArea>
      </DocxViewerBody>
    </DocxViewerFrame>
  )
}

"use client"

import * as React from "react"
import { Download } from "lucide-react"

import { cn } from "@/lib/utils"
import {
  ViewerDownloadError,
  type ViewerDownloadAction,
  type ViewerDownloadPayload,
} from "@/lib/viewer-download"

import { Button, buttonVariants } from "./button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "./dropdown-menu"

export interface TriggerViewerDownloadOptions {
  signal?: AbortSignal
}

export async function triggerViewerDownload(
  action: ViewerDownloadAction,
  options?: TriggerViewerDownloadOptions
): Promise<void> {
  if (action.isDisabled) {
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "disabled",
      message: "This download is disabled.",
    })
  }

  let payload: ViewerDownloadPayload
  try {
    payload = await action.getPayload(options)
  } catch (error) {
    if (isAbortError(error)) {
      throw new ViewerDownloadError({
        actionId: action.id,
        kind: "aborted",
        message: "Download was cancelled.",
        cause: error,
      })
    }
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "payload_failed",
      message: "Could not prepare this download.",
      cause: error,
    })
  }

  if (payload.kind === "none") return
  if (payload.kind === "href") {
    try {
      clickDownload(payload.href, action.fileName)
    } catch (error) {
      throw new ViewerDownloadError({
        actionId: action.id,
        kind: "unsupported",
        message: "Could not start this download.",
        cause: error,
      })
    }
    return
  }

  try {
    const blob =
      payload.kind === "blob"
        ? payload.blob
        : new Blob([payload.text], {
            type: payload.mimeType ?? "text/plain;charset=utf-8",
          })
    const url = URL.createObjectURL(blob)
    try {
      clickDownload(url, action.fileName)
    } finally {
      URL.revokeObjectURL(url)
    }
  } catch (error) {
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "unsupported",
      message: "Could not start this download.",
      cause: error,
    })
  }
}

export type ViewerDownloadErrorHandler = (
  error: ViewerDownloadError,
  action: ViewerDownloadAction
) => void

export interface ViewerDownloadTrigger {
  pendingActionId: string | null
  triggerDownload: (action: ViewerDownloadAction) => void
}

export interface ViewerDownloadTriggerOptions {
  /** Reports non-aborted action failures; visible failure UI belongs to consumers. */
  onError?: ViewerDownloadErrorHandler
  resetKey?: unknown
}

export interface ViewerDownloadControlProps {
  actions: Array<ViewerDownloadAction | null | undefined>
  variant?: React.ComponentProps<typeof Button>["variant"]
  size?: React.ComponentProps<typeof Button>["size"]
  className?: string
  showLabel?: boolean
  /** Reports non-aborted action failures; visible failure UI belongs to consumers. */
  onError?: ViewerDownloadErrorHandler
}

export interface ViewerDownloadButtonProps
  extends Omit<ViewerDownloadControlProps, "actions"> {
  action: ViewerDownloadAction | null
}

export interface ViewerDownloadMenuProps
  extends Omit<ViewerDownloadControlProps, "actions"> {
  actions: ViewerDownloadAction[]
}

export function useViewerDownloadHref(
  action: ViewerDownloadAction | null
): string | null {
  const shouldCreateHref = action?.origin !== "derived"
  const payload = shouldCreateHref ? getSynchronousPayload(action) : null

  return shouldCreateHref && payload?.kind === "href" ? payload.href : null
}

export function useViewerDownloadTrigger({
  onError,
  resetKey = "",
}: ViewerDownloadTriggerOptions = {}): ViewerDownloadTrigger {
  const [pendingActionId, setPendingActionId] = React.useState<string | null>(
    null
  )
  const abortControllerRef = React.useRef<AbortController | null>(null)

  React.useEffect(() => {
    return () => {
      abortControllerRef.current?.abort()
      abortControllerRef.current = null
    }
  }, [resetKey])

  const triggerDownload = React.useCallback(
    (action: ViewerDownloadAction) => {
      abortControllerRef.current?.abort()
      const abortController = new AbortController()
      abortControllerRef.current = abortController
      setPendingActionId(action.id)
      void triggerViewerDownload(action, { signal: abortController.signal })
        .catch((error) => {
          reportDownloadError(error, action, onError)
        })
        .finally(() => {
          if (abortControllerRef.current === abortController) {
            abortControllerRef.current = null
            setPendingActionId(null)
          }
        })
    },
    [onError]
  )

  return { pendingActionId, triggerDownload }
}

export function ViewerDownloadControl({
  actions,
  variant = "ghost",
  size = "icon-sm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadControlProps) {
  const enabledActions = actions.filter(
    (action): action is ViewerDownloadAction => Boolean(action)
  )

  if (enabledActions.length <= 1) {
    return (
      <ViewerDownloadButton
        action={enabledActions[0] ?? null}
        variant={variant}
        size={size}
        className={className}
        showLabel={showLabel}
        onError={onError}
      />
    )
  }

  return (
    <ViewerDownloadMenu
      actions={enabledActions}
      variant={variant}
      size={size}
      className={className}
      showLabel={showLabel}
      onError={onError}
    />
  )
}

export function ViewerDownloadButton({
  action,
  variant = "ghost",
  size = "icon-sm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadButtonProps) {
  const href = useViewerDownloadHref(action)
  const label = action?.label ?? "Download"
  const disabled = !action || action.isDisabled
  const hasDownloadHref = Boolean(href)
  const { pendingActionId, triggerDownload } = useViewerDownloadTrigger({
    onError,
    resetKey: action,
  })
  const isPending = Boolean(action && pendingActionId === action.id)

  const handleClick = React.useCallback(() => {
    if (!action || hasDownloadHref) return
    triggerDownload(action)
  }, [action, hasDownloadHref, triggerDownload])

  if (href) {
    return (
      <a
        href={href}
        download={action?.fileName}
        className={cn(buttonVariants({ variant, size }), className)}
        aria-label={label}
        title={label}
        data-slot="button"
      >
        <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
        {showLabel ? label : null}
      </a>
    )
  }

  return (
    <Button
      variant={variant}
      size={size}
      className={className}
      aria-label={label}
      title={label}
      disabled={disabled}
      loading={isPending}
      onClick={handleClick}
    >
      <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
      {showLabel ? label : null}
    </Button>
  )
}

export function ViewerDownloadMenu({
  actions,
  variant = "ghost",
  size = "icon-sm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadMenuProps) {
  const actionSetKey = actions.map((action) => action.id).join("\u0000")
  const label = "Download"
  const { pendingActionId, triggerDownload } = useViewerDownloadTrigger({
    onError,
    resetKey: actionSetKey,
  })

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            variant={variant}
            size={size}
            className={className}
            aria-label={label}
            title={label}
            loading={pendingActionId != null}
          >
            <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
            {showLabel ? label : null}
          </Button>
        }
      />
      <DropdownMenuContent align="end">
        {actions.map((action) => (
          <DropdownMenuItem
            key={action.id}
            disabled={action.isDisabled || pendingActionId != null}
            onClick={() => triggerDownload(action)}
          >
            <Download />
            <span>{action.label}</span>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

function clickDownload(href: string, fileName: string) {
  const anchor = document.createElement("a")
  anchor.href = href
  anchor.download = fileName
  anchor.rel = "noreferrer"
  document.body.appendChild(anchor)
  anchor.click()
  anchor.remove()
}

function getSynchronousPayload(
  action: ViewerDownloadAction | null
): ViewerDownloadPayload | null {
  if (!action || action.isDisabled) return null
  const payload = action.getPayload()
  return payload instanceof Promise ? null : payload
}

function reportDownloadError(
  error: unknown,
  action: ViewerDownloadAction,
  onError: ViewerDownloadErrorHandler | undefined
) {
  if (!(error instanceof ViewerDownloadError)) return
  if (error.kind === "aborted") return
  onError?.(error, action)
}

function isAbortError(error: unknown) {
  return error instanceof DOMException && error.name === "AbortError"
}

import {
  createBlobDownloadAction,
  createHrefDownloadAction,
  createTextDownloadAction,
  type ViewerDownloadAction,
} from "@/lib/viewer-download"
import {
  isAbortError,
  ResourceError,
  type ResourceTooLargeReason,
} from "@/lib/viewer-errors"
import {
  resolveViewerDescriptor,
  type BlobViewerSource,
  type FileCategory,
  type TextSource,
  type UrlViewerSource,
  type ViewerDescriptor,
  type ViewerSource,
} from "@/lib/viewer-source"

export interface ResourceReadOptions {
  signal?: AbortSignal
}

export interface TextReadOptions extends ResourceReadOptions {
  maxBytes?: number
  maxLines?: number
}

export interface ByteRange {
  start: number
  end: number
}

export interface ByteRangeResult {
  buffer: ArrayBuffer
  contentRange?: {
    start: number
    end: number
    total: number | null
  }
  isComplete: boolean
}

export interface ViewerResourceKeys {
  readonly load: string
  readonly presentation: string
  readonly resource: string
}

export type ViewerResourcePayload =
  | { kind: "url"; url: string }
  | { kind: "blob"; blob: Blob }
  | { kind: "text"; text: string }

export interface ViewerResourceContent {
  readonly key: string
  readonly sourceKind: ViewerSource["kind"]
  readonly directUrl: string | null
  readonly mimeType?: string
  readonly payload: ViewerResourcePayload
  readBlob(options?: ResourceReadOptions): Promise<Blob>
  readBytes(options?: ResourceReadOptions): Promise<ArrayBuffer>
  readText(options?: TextReadOptions): Promise<string>
  readStream(options?: ResourceReadOptions): Promise<ReadableStream<Uint8Array>>
  readRange(
    range: ByteRange,
    options?: ResourceReadOptions
  ): Promise<ByteRangeResult>
}

export type ViewerContentIdentity = Pick<
  ViewerResourceContent,
  "key" | "sourceKind"
>

export type ViewerContentDirectUrl = ViewerContentIdentity &
  Pick<ViewerResourceContent, "directUrl">

export type ViewerContentPayload = ViewerContentIdentity &
  Pick<ViewerResourceContent, "payload">

export type ViewerContentMime = ViewerContentIdentity &
  Pick<ViewerResourceContent, "mimeType">

export type ViewerContentBlob = ViewerContentIdentity &
  Pick<ViewerResourceContent, "readBlob">

export type ViewerContentBytes = ViewerContentIdentity &
  Pick<ViewerResourceContent, "readBytes">

export type ViewerContentText = ViewerContentIdentity &
  Pick<ViewerResourceContent, "readText">

export type ViewerContentStream = ViewerContentIdentity &
  Pick<ViewerResourceContent, "readStream">

export type ViewerContentRange = ViewerContentIdentity &
  Pick<ViewerResourceContent, "readRange">

export interface ViewerResource {
  readonly descriptor: ViewerDescriptor
  readonly sourceKind: ViewerSource["kind"]
  readonly keys: ViewerResourceKeys
  readonly identityKey: string
  readonly fileName: string
  readonly mimeType?: string
  readonly content: ViewerResourceContent
  readonly originalDownload: ViewerDownloadAction
}

const URL_RESOURCE_REGISTRY_MAX = 128
const TEXT_RESOURCE_REGISTRY_MAX = 64
// LF, CR, CRLF, LINE SEPARATOR (U+2028), and PARAGRAPH SEPARATOR (U+2029) — the
// ECMAScript LineTerminator set, matching what a browser breaks on in a
// `white-space: pre` block. Kept in sync with text-viewer-resource's splitter.
const TEXT_LINE_BREAK_PATTERN = /\r\n|[\n\r\u2028\u2029]/g

const urlViewerResourceRegistry = new Map<string, ViewerResource>()
const urlViewerResourceContentRegistry = new Map<
  string,
  ViewerResourceContent
>()
const textViewerResourceRegistry = new Map<string, ViewerResource>()
const textViewerResourceContentRegistry = new Map<
  string,
  ViewerResourceContent
>()
let blobViewerResourceRegistry = new WeakMap<
  Blob,
  Map<string, ViewerResource>
>()
let blobViewerResourceContentRegistry = new WeakMap<
  Blob,
  Map<string, ViewerResourceContent>
>()
const blobObjectKeys = new WeakMap<Blob, string>()
let nextBlobObjectKey = 0

export function createViewerResource(
  source: ViewerSource,
  category?: FileCategory
): ViewerResource {
  const descriptor = resolveViewerDescriptor({ source, category })
  const keys = viewerResourceKeys(source, descriptor)

  if (source.kind === "url") {
    return internUrlResource(source, descriptor, keys)
  }
  if (source.kind === "blob") {
    return internBlobResource(source, descriptor, keys)
  }
  return internTextResource(source, descriptor, keys)
}

export function clearViewerResourceRegistryForTests() {
  urlViewerResourceRegistry.clear()
  urlViewerResourceContentRegistry.clear()
  textViewerResourceRegistry.clear()
  textViewerResourceContentRegistry.clear()
  blobViewerResourceRegistry = new WeakMap()
  blobViewerResourceContentRegistry = new WeakMap()
}

function internUrlResource(
  source: UrlViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys
): ViewerResource {
  const cached = urlViewerResourceRegistry.get(keys.resource)
  if (cached) return cached

  const resource = createUrlResource(source, descriptor, keys)
  urlViewerResourceRegistry.set(keys.resource, resource)
  pruneUrlResourceRegistry()
  return resource
}

function internBlobResource(
  source: BlobViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys
): ViewerResource {
  let resources = blobViewerResourceRegistry.get(source.blob)
  if (!resources) {
    resources = new Map()
    blobViewerResourceRegistry.set(source.blob, resources)
  }

  const cached = resources.get(keys.resource)
  if (cached) return cached

  const resource = createBlobResource(source, descriptor, keys)
  resources.set(keys.resource, resource)
  return resource
}

function internTextResource(
  source: TextSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys
): ViewerResource {
  const cached = textViewerResourceRegistry.get(keys.resource)
  if (cached) return cached

  const resource = createTextResource(source, descriptor, keys)
  textViewerResourceRegistry.set(keys.resource, resource)
  pruneTextResourceRegistry()
  return resource
}

function pruneUrlResourceRegistry() {
  while (urlViewerResourceRegistry.size > URL_RESOURCE_REGISTRY_MAX) {
    const firstKey = urlViewerResourceRegistry.keys().next().value
    if (!firstKey) return
    urlViewerResourceRegistry.delete(firstKey)
  }
}

function pruneUrlResourceContentRegistry() {
  while (urlViewerResourceContentRegistry.size > URL_RESOURCE_REGISTRY_MAX) {
    const firstKey = urlViewerResourceContentRegistry.keys().next().value
    if (!firstKey) return
    urlViewerResourceContentRegistry.delete(firstKey)
  }
}

function pruneTextResourceRegistry() {
  while (textViewerResourceRegistry.size > TEXT_RESOURCE_REGISTRY_MAX) {
    const firstKey = textViewerResourceRegistry.keys().next().value
    if (!firstKey) return
    textViewerResourceRegistry.delete(firstKey)
  }
}

function pruneTextResourceContentRegistry() {
  while (textViewerResourceContentRegistry.size > TEXT_RESOURCE_REGISTRY_MAX) {
    const firstKey = textViewerResourceContentRegistry.keys().next().value
    if (!firstKey) return
    textViewerResourceContentRegistry.delete(firstKey)
  }
}

function viewerResourceKeys(
  source: ViewerSource,
  descriptor: ViewerDescriptor
): ViewerResourceKeys {
  const load = viewerResourceLoadKey(source)
  const presentation = viewerResourcePresentationKey(source, descriptor)
  return {
    load,
    presentation,
    resource: [load, presentation].join("\u0000"),
  }
}

function viewerResourceLoadKey(source: ViewerSource) {
  return [
    source.kind,
    source.identityKey ?? "",
    sourceMimeType(source) ?? "",
    directLoadCacheKey(source),
    payloadCacheKey(source),
  ].join("\u0000")
}

function viewerResourcePresentationKey(
  source: ViewerSource,
  descriptor: ViewerDescriptor
) {
  return [
    descriptor.category,
    descriptor.displayName,
    descriptor.fileName,
    descriptor.mimeType ?? "",
    downloadCacheKey(source),
  ].join("\u0000")
}

function directLoadCacheKey(source: ViewerSource) {
  return source.kind === "url" ? source.url : ""
}

function downloadCacheKey(source: ViewerSource) {
  if (source.kind === "text") return ""
  return source.downloadUrl ?? ""
}

function payloadCacheKey(source: ViewerSource) {
  if (source.kind === "url") return ""
  if (source.kind === "blob") return blobObjectKey(source.blob)
  return `text:${source.text.length}:${hashString(source.text)}`
}

function sourceMimeType(source: ViewerSource) {
  if (source.kind === "blob") return source.mimeType ?? source.blob.type
  return source.mimeType
}

function blobObjectKey(blob: Blob) {
  let key = blobObjectKeys.get(blob)
  if (!key) {
    nextBlobObjectKey += 1
    key = `blob-object:${nextBlobObjectKey}`
    blobObjectKeys.set(blob, key)
  }
  return key
}

function hashString(text: string) {
  let hash = 0x811c9dc5
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index)
    hash = Math.imul(hash, 0x01000193)
  }
  return (hash >>> 0).toString(36)
}

export function blobSource(
  bytes: Blob | ArrayBuffer | Uint8Array,
  metadata: {
    identityKey: string
    fileName?: string
    mimeType?: string
    downloadUrl?: string
  }
): BlobViewerSource {
  const blob =
    bytes instanceof Blob
      ? bytes
      : new Blob(
          [bytes instanceof ArrayBuffer ? bytes : new Uint8Array(bytes)],
          {
            type: metadata.mimeType ?? "",
          }
        )
  return {
    kind: "blob",
    blob,
    fileName: metadata.fileName,
    mimeType: metadata.mimeType ?? blob.type,
    downloadUrl: metadata.downloadUrl,
    identityKey: metadata.identityKey,
  }
}

function createUrlResource(
  source: UrlViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys
): ViewerResource {
  const content = internUrlResourceContent(source, keys)
  const originalDownload = createHrefDownloadAction({
    id: "download-original",
    label: "Download",
    href: source.downloadUrl ?? source.url,
    fileName: descriptor.fileName,
  })

  return resourceBase(source, descriptor, keys, { content, originalDownload })
}

function internUrlResourceContent(
  source: UrlViewerSource,
  keys: ViewerResourceKeys
): ViewerResourceContent {
  const cached = urlViewerResourceContentRegistry.get(keys.load)
  if (cached) return cached

  const content = resourceContentBase(source, keys, {
    directUrl: source.url,
    payload: { kind: "url", url: source.url },
    readBlob: async ({ signal } = {}) => {
      const response = await fetchResource(source.url, { signal })
      validateFullContentResponse(response)
      return readResponseBlob(response)
    },
    readBytes: async ({ signal } = {}) => {
      const response = await fetchResource(source.url, { signal })
      validateFullContentResponse(response)
      return readResponseArrayBuffer(response)
    },
    readText: async ({ signal, maxBytes, maxLines } = {}) => {
      const response = await fetchResource(source.url, { signal })
      return readBoundedResponseText(response, { maxBytes, maxLines })
    },
    readStream: async ({ signal } = {}) => {
      const response = await fetchResource(source.url, { signal })
      validateFullContentResponse(response)
      if (!response.body) {
        if (response.status === 204 || response.status === 205) {
          return emptyByteStream()
        }
        throw new ResourceError({
          kind: "unsupported_capability",
          message: "This response cannot be streamed.",
        })
      }
      return response.body
    },
    readRange: async (range, { signal } = {}) => {
      validateByteRange(range)
      const { start, end } = range
      const response = await fetchResource(source.url, {
        signal,
        headers: { Range: `bytes=${start}-${end}` },
      })
      const buffer = await readResponseArrayBuffer(response)
      const contentRange = parseContentRange(
        response.headers.get("content-range")
      )
      validateUrlRangeResponse({
        bufferLength: buffer.byteLength,
        contentRange,
        range,
        status: response.status,
      })
      return {
        buffer,
        contentRange,
        isComplete: isByteRangeComplete({
          bufferLength: buffer.byteLength,
          contentRange,
          requestedLength: end - start + 1,
          status: response.status,
        }),
      }
    },
  })
  urlViewerResourceContentRegistry.set(keys.load, content)
  pruneUrlResourceContentRegistry()
  return content
}

function emptyByteStream() {
  return new ReadableStream<Uint8Array>({
    start(controller) {
      controller.close()
    },
  })
}

function createBlobResource(
  source: BlobViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys
): ViewerResource {
  const blob = source.blob
  const content = internBlobResourceContent(source, keys)
  const originalDownload = source.downloadUrl
    ? createHrefDownloadAction({
        id: "download-original",
        label: "Download",
        href: source.downloadUrl,
        fileName: descriptor.fileName,
      })
    : createBlobDownloadAction({
        id: "download-original",
        label: "Download",
        blob,
        fileName: descriptor.fileName,
      })

  return resourceBase(source, descriptor, keys, { content, originalDownload })
}

function internBlobResourceContent(
  source: BlobViewerSource,
  keys: ViewerResourceKeys
): ViewerResourceContent {
  const blob = source.blob
  let contents = blobViewerResourceContentRegistry.get(blob)
  if (!contents) {
    contents = new Map()
    blobViewerResourceContentRegistry.set(blob, contents)
  }

  const cached = contents.get(keys.load)
  if (cached) return cached

  const content = resourceContentBase(source, keys, {
    directUrl: null,
    payload: { kind: "blob", blob },
    readBlob: async () => blob,
    readBytes: async () => blob.arrayBuffer(),
    readText: async ({ maxBytes, maxLines } = {}) =>
      readBoundedBlobText(blob, { maxBytes, maxLines }),
    readStream: async () => blob.stream(),
    readRange: async (range) => {
      validateByteRange(range)
      const { start, end } = range
      validateKnownByteRangeStart(start, blob.size)
      const rangeBlob = blob.slice(start, end + 1)
      return {
        buffer: await rangeBlob.arrayBuffer(),
        contentRange: {
          start,
          end: Math.min(end, blob.size - 1),
          total: blob.size,
        },
        isComplete: end >= blob.size - 1,
      }
    },
  })
  contents.set(keys.load, content)
  return content
}

function createTextResource(
  source: TextSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys
): ViewerResource {
  const content = internTextResourceContent(source, keys)
  const originalDownload = createTextDownloadAction({
    id: "download-original",
    label: "Download",
    text: source.text,
    fileName: descriptor.fileName,
    mimeType: descriptor.mimeType,
  })

  return resourceBase(source, descriptor, keys, { content, originalDownload })
}

function internTextResourceContent(
  source: TextSource,
  keys: ViewerResourceKeys
): ViewerResourceContent {
  const cached = textViewerResourceContentRegistry.get(keys.load)
  if (cached) return cached

  const content = resourceContentBase(source, keys, {
    directUrl: null,
    payload: { kind: "text", text: source.text },
    readBlob: async () =>
      new Blob([source.text], {
        type: "text/plain;charset=utf-8",
      }),
    readBytes: async () =>
      typedArrayBuffer(new TextEncoder().encode(source.text)),
    readText: async ({ maxBytes, maxLines } = {}) =>
      readBoundedInlineText(source.text, { maxBytes, maxLines }),
    readStream: async () => new Blob([source.text]).stream(),
    readRange: async (range) => {
      validateByteRange(range)
      const { start, end } = range
      const buffer = new TextEncoder().encode(source.text)
      validateKnownByteRangeStart(start, buffer.byteLength)
      const slice = buffer.slice(start, end + 1)
      return {
        buffer: typedArrayBuffer(slice),
        contentRange: {
          start,
          end: Math.min(end, buffer.byteLength - 1),
          total: buffer.byteLength,
        },
        isComplete: end >= buffer.byteLength - 1,
      }
    },
  })
  textViewerResourceContentRegistry.set(keys.load, content)
  pruneTextResourceContentRegistry()
  return content
}

function resourceBase(
  source: ViewerSource,
  descriptor: ViewerDescriptor,
  keys: ViewerResourceKeys,
  options: {
    content: ViewerResourceContent
    originalDownload: ViewerDownloadAction
  }
): ViewerResource {
  const { content, originalDownload } = options
  return Object.freeze({
    descriptor,
    sourceKind: source.kind,
    keys,
    identityKey: descriptor.identityKey,
    fileName: descriptor.fileName,
    mimeType: descriptor.mimeType,
    content,
    originalDownload,
  })
}

function resourceContentBase(
  source: ViewerSource,
  keys: ViewerResourceKeys,
  methods: Omit<ViewerResourceContent, "key" | "sourceKind" | "mimeType">
): ViewerResourceContent {
  return Object.freeze({
    key: keys.load,
    sourceKind: source.kind,
    mimeType: sourceMimeType(source),
    ...methods,
  })
}

function typedArrayBuffer(bytes: Uint8Array): ArrayBuffer {
  return bytes.buffer.slice(
    bytes.byteOffset,
    bytes.byteOffset + bytes.byteLength
  ) as ArrayBuffer
}

async function fetchResource(
  input: RequestInfo | URL,
  init?: RequestInit
): Promise<Response> {
  let response: Response
  try {
    response = await fetch(input, init)
  } catch (error) {
    if (isAbortError(error)) {
      throw new ResourceError({
        kind: "aborted",
        message: "Loading was cancelled.",
        cause: error,
      })
    }
    throw new ResourceError({
      kind: "fetch_failed",
      message: "Could not fetch this resource.",
      cause: error,
    })
  }

  if (!response.ok && response.status !== 206) {
    throw new ResourceError({
      kind: "http_error",
      message: `Failed to load resource: ${response.status}`,
      status: response.status,
    })
  }

  return response
}

async function readBoundedResponseText(
  response: Response,
  bounds: { maxBytes?: number; maxLines?: number }
) {
  validateFullContentResponse(response)

  const maxBytes = bounds.maxBytes
  if (
    isContentLengthOverLimit(response.headers.get("content-length"), maxBytes)
  ) {
    throw tooLarge("bytes")
  }

  const body = response.body
  if (!body) {
    const buffer = await readResponseArrayBuffer(response)
    if (maxBytes != null && buffer.byteLength > maxBytes) {
      throw tooLarge("bytes")
    }
    const text = new TextDecoder().decode(buffer)
    assertLineLimit(text, bounds.maxLines)
    return text
  }

  const reader = body.getReader()
  const decoder = new TextDecoder()
  const lineLimitTracker = createLineLimitTracker(bounds.maxLines)
  let receivedBytes = 0
  let text = ""

  while (true) {
    const { done, value } = await readResponseStreamChunk(reader)
    if (done) break
    receivedBytes += value.byteLength
    if (maxBytes != null && receivedBytes > maxBytes) {
      await cancelReaderSilently(reader)
      throw tooLarge("bytes")
    }
    const chunkText = decoder.decode(value, { stream: true })
    try {
      lineLimitTracker.push(chunkText)
    } catch (error) {
      await cancelReaderSilently(reader)
      throw error
    }
    text += chunkText
  }

  const finalText = decoder.decode()
  lineLimitTracker.push(finalText)
  text += finalText
  assertLineLimit(text, bounds.maxLines)
  return text
}

function isContentLengthOverLimit(
  contentLength: string | null,
  maxBytes: number | undefined
) {
  if (maxBytes == null || contentLength == null) return false

  const normalizedLength = contentLength.trim().replace(/^0+(?=\d)/, "")
  if (!/^\d+$/.test(normalizedLength)) return false

  const maxLength = String(maxBytes)
  return (
    normalizedLength.length > maxLength.length ||
    (normalizedLength.length === maxLength.length &&
      normalizedLength > maxLength)
  )
}

function validateFullContentResponse(response: Response) {
  if (response.status === 206) {
    throw new ResourceError({
      kind: "partial_content",
      message: "Full response returned partial content.",
      status: response.status,
    })
  }
}

async function readResponseStreamChunk(
  reader: ReadableStreamDefaultReader<Uint8Array>
) {
  try {
    return await reader.read()
  } catch (error) {
    throw resourceReadError(error)
  }
}

async function readResponseArrayBuffer(response: Response) {
  try {
    return await response.arrayBuffer()
  } catch (error) {
    throw resourceReadError(error)
  }
}

async function readResponseBlob(response: Response) {
  try {
    return await response.blob()
  } catch (error) {
    throw resourceReadError(error)
  }
}

function resourceReadError(error: unknown) {
  if (isAbortError(error)) {
    return new ResourceError({
      kind: "aborted",
      message: "Loading was cancelled.",
      cause: error,
    })
  }
  return new ResourceError({
    kind: "fetch_failed",
    message: "Could not read this resource.",
    cause: error,
  })
}

async function readBoundedBlobText(
  blob: Blob,
  bounds: { maxBytes?: number; maxLines?: number }
) {
  if (bounds.maxBytes != null && blob.size > bounds.maxBytes) {
    throw tooLarge("bytes")
  }
  const text = await blob.text()
  assertLineLimit(text, bounds.maxLines)
  return text
}

function readBoundedInlineText(
  text: string,
  { maxBytes, maxLines }: { maxBytes?: number; maxLines?: number }
) {
  // For inline sources the string *is* the resource, so its UTF-8 byte length
  // is the authoritative size to measure against maxBytes.
  if (
    maxBytes != null &&
    new TextEncoder().encode(text).byteLength > maxBytes
  ) {
    throw tooLarge("bytes")
  }
  assertLineLimit(text, maxLines)
  return text
}

// Used after a transferred-byte check has already enforced maxBytes (URL/blob).
// Re-encoding the decoded text here would double-count: invalid UTF-8 decodes to
// U+FFFD (3 bytes each), inflating the measured size past the real wire bytes
// and falsely rejecting small resources as "too large".
function assertLineLimit(text: string, maxLines: number | undefined) {
  if (
    maxLines != null &&
    text.split(TEXT_LINE_BREAK_PATTERN).length > maxLines
  ) {
    throw tooLarge("lines")
  }
}

function tooLarge(reason: ResourceTooLargeReason) {
  return new ResourceError({
    kind: "too_large",
    tooLargeReason: reason,
    message: `Resource exceeds ${reason} limit.`,
  })
}

async function cancelReaderSilently(
  reader: ReadableStreamDefaultReader<Uint8Array>
) {
  try {
    await reader.cancel()
  } catch {
    // Preserve the user-facing load failure; cancellation is best-effort cleanup.
  }
}

function validateByteRange({ start, end }: ByteRange) {
  if (
    !Number.isSafeInteger(start) ||
    !Number.isSafeInteger(end) ||
    start < 0 ||
    end < start
  ) {
    throw new ResourceError({
      kind: "invalid_range",
      message: "Byte range must use non-negative integer bounds.",
    })
  }
}

function validateKnownByteRangeStart(start: number, total: number) {
  if (start > 0 && start >= total) {
    throw new ResourceError({
      kind: "invalid_range",
      message: "Byte range starts past the available resource.",
    })
  }
}

function validateUrlRangeResponse({
  bufferLength,
  contentRange,
  range,
  status,
}: {
  bufferLength: number
  contentRange: ByteRangeResult["contentRange"]
  range: ByteRange
  status: number
}) {
  if (status === 200) {
    if (range.start !== 0 || bufferLength > range.end - range.start + 1) {
      throw new ResourceError({
        kind: "invalid_range",
        message: "Full response does not match the requested byte range.",
      })
    }
    return
  }
  if (status !== 206) {
    throw new ResourceError({
      kind: "invalid_range",
      message: "Range response must return full or partial content.",
    })
  }
  if (!contentRange) {
    throw new ResourceError({
      kind: "invalid_range",
      message: "Partial content response is missing a valid byte range.",
    })
  }
  const declaredLength = contentRange.end - contentRange.start + 1
  if (
    contentRange.start !== range.start ||
    contentRange.end < contentRange.start ||
    contentRange.end > range.end ||
    (contentRange.total != null && contentRange.end >= contentRange.total) ||
    declaredLength !== bufferLength
  ) {
    throw new ResourceError({
      kind: "invalid_range",
      message: "Response byte range does not match the requested range.",
    })
  }
}

function isByteRangeComplete({
  bufferLength,
  contentRange,
  requestedLength,
  status,
}: {
  bufferLength: number
  contentRange: ByteRangeResult["contentRange"]
  requestedLength: number
  status: number
}) {
  if (status === 200) return true
  if (contentRange?.total != null) {
    if (contentRange.total <= 0) return true
    return contentRange.end >= contentRange.total - 1
  }
  if (contentRange) return false
  return bufferLength < requestedLength
}

function isStandaloneLineBreak(character: string) {
  const code = character.charCodeAt(0)
  return code === 0x0a || code === 0x2028 || code === 0x2029
}

function createLineLimitTracker(maxLines: number | undefined) {
  let lineCount = 1
  let previousWasCR = false

  return {
    push(text: string) {
      if (maxLines == null || text.length === 0) return

      for (const character of text) {
        if (previousWasCR) {
          previousWasCR = false
          if (character === "\n") continue
        }

        if (character === "\r") {
          lineCount += 1
          previousWasCR = true
        } else if (isStandaloneLineBreak(character)) {
          // LF, plus LINE/PARAGRAPH SEPARATOR (U+2028/U+2029); none pair with CR.
          lineCount += 1
        }

        if (lineCount > maxLines) {
          throw tooLarge("lines")
        }
      }
    },
  }
}

function parseContentRange(value: string | null) {
  if (!value) return undefined
  const match = value.match(/^bytes\s+(\d+)-(\d+)\/(\d+|\*)\s*$/i)
  if (!match) return undefined
  const start = parseContentRangeNumber(match[1])
  const end = parseContentRangeNumber(match[2])
  const total =
    match[3] === "*" ? null : parseContentRangeNumber(match[3] ?? "")
  if (start == null || end == null || total === undefined) return undefined
  return {
    start,
    end,
    total,
  }
}

function parseContentRangeNumber(value: string) {
  const number = Number(value)
  return Number.isSafeInteger(number) ? number : undefined
}

export type ViewerDownloadOrigin = "original" | "derived"

export type ViewerDownloadPayload =
  | { kind: "href"; href: string }
  | { kind: "blob"; blob: Blob }
  | { kind: "text"; text: string; mimeType?: string }
  | { kind: "none" }

export interface ViewerDownloadAction {
  id: string
  label: string
  fileName: string
  origin: ViewerDownloadOrigin
  isDisabled?: boolean
  getPayload: (options?: {
    signal?: AbortSignal
  }) => ViewerDownloadPayload | Promise<ViewerDownloadPayload>
}

export type ViewerDownloadErrorKind =
  | "disabled"
  | "aborted"
  | "payload_failed"
  | "unsupported"

export class ViewerDownloadError extends Error {
  readonly kind: ViewerDownloadErrorKind
  readonly actionId: string
  override readonly cause?: unknown

  constructor({
    actionId,
    kind,
    message,
    cause,
  }: {
    actionId: string
    kind: ViewerDownloadErrorKind
    message: string
    cause?: unknown
  }) {
    super(message)
    this.name = "ViewerDownloadError"
    this.actionId = actionId
    this.kind = kind
    this.cause = cause
  }
}

export function createHrefDownloadAction({
  id,
  label = "Download",
  href,
  fileName,
  origin = "original",
}: {
  id: string
  label?: string
  href: string
  fileName: string
  origin?: ViewerDownloadOrigin
}): ViewerDownloadAction {
  return {
    id,
    label,
    fileName,
    origin,
    getPayload: () => ({ kind: "href", href }),
  }
}

export function createBlobDownloadAction({
  id,
  label = "Download",
